export const MCQS: MCQ[] = [
  // ============ Anatomy & Embryology (15) ============
  { id: 1, topic: 'Anatomy & Embryology', q: 'Which extraocular muscle is innervated by the trochlear nerve (CN IV)?', options: ['Superior rectus', 'Superior oblique', 'Inferior oblique', 'Lateral rectus', 'Medial rectus'], correct: 1, explanation: 'The trochlear nerve solely innervates the superior oblique muscle. CN VI supplies lateral rectus; CN III supplies the rest.' },
  { id: 2, topic: 'Anatomy & Embryology', q: 'The arterial supply to the optic nerve head is primarily from:', options: ['Central retinal artery', 'Short posterior ciliary arteries', 'Long posterior ciliary arteries', 'Lacrimal artery', 'Ophthalmic artery directly'], correct: 1, explanation: 'The short posterior ciliary arteries (via the circle of Zinn-Haller) supply the optic nerve head. The central retinal artery supplies inner retina only.' },
  { id: 3, topic: 'Anatomy & Embryology', q: 'Which structure is derived from neural crest?', options: ['Lens', 'Retina', 'Corneal stroma', 'Vitreous primary', 'RPE'], correct: 2, explanation: 'Corneal stroma, endothelium, sclera, choroidal stroma, and trabecular meshwork are neural crest derived. Lens and retina are surface ectoderm and neuroectoderm respectively.' },
  { id: 4, topic: 'Anatomy & Embryology', q: 'The fovea centralis is approximately how many disc diameters temporal to the optic disc?', options: ['1 DD', '1.5 DD', '2 DD', '2.5 DD', '4 DD'], correct: 3, explanation: 'The fovea is ~2.5 disc diameters (4 mm) temporal and 0.8 mm inferior to the center of the optic disc.' },
  { id: 5, topic: 'Anatomy & Embryology', q: 'Bruch\'s membrane lies between:', options: ['NFL and ganglion cell layer', 'RPE and choriocapillaris', 'Photoreceptors and RPE', 'Sclera and choroid', 'ILM and NFL'], correct: 1, explanation: 'Bruch\'s membrane is the basement complex separating the RPE from the choriocapillaris. It thickens with age and is involved in AMD.' },
  { id: 6, topic: 'Anatomy & Embryology', q: 'The blood supply of the iris is from:', options: ['Central retinal artery', 'Major arterial circle (long posterior ciliary)', 'Short posterior ciliary arteries', 'Vortex veins', 'Lacrimal artery'], correct: 1, explanation: 'The iris is supplied by the major arterial circle formed by the two long posterior ciliary arteries and anterior ciliary arteries.' },
  { id: 7, topic: 'Anatomy & Embryology', q: 'The lacrimal sac drains into the nasal cavity via the:', options: ['Superior meatus', 'Middle meatus', 'Inferior meatus', 'Sphenoethmoidal recess', 'Vestibule'], correct: 2, explanation: 'The nasolacrimal duct opens into the inferior meatus beneath the inferior turbinate (valve of Hasner).' },
  { id: 8, topic: 'Anatomy & Embryology', q: 'Which extraocular muscle does NOT originate from the annulus of Zinn?', options: ['Superior rectus', 'Inferior rectus', 'Inferior oblique', 'Medial rectus', 'Lateral rectus'], correct: 2, explanation: 'The inferior oblique originates from the orbital plate of the maxilla near the lacrimal fossa, not from the annulus of Zinn.' },
  { id: 9, topic: 'Anatomy & Embryology', q: 'The thinnest part of the sclera is at:', options: ['Limbus', 'Equator', 'Posterior pole', 'Insertions of rectus muscles', 'Lamina cribrosa'], correct: 3, explanation: 'The sclera is thinnest (~0.3 mm) just posterior to the recti insertions, a high-risk zone for staphyloma and perforation.' },
  { id: 10, topic: 'Anatomy & Embryology', q: 'Müller cells are:', options: ['Photoreceptors', 'Bipolar interneurons', 'Glial cells spanning all retinal layers', 'Pigmented cells of the RPE', 'Cells of the ciliary epithelium'], correct: 2, explanation: 'Müller cells are the principal glial cells of the retina, spanning from the ILM to the external limiting membrane.' },
  { id: 11, topic: 'Anatomy & Embryology', q: 'The pupillary light reflex pathway synapses in the:', options: ['Lateral geniculate nucleus', 'Pretectal nucleus and Edinger-Westphal nucleus', 'Superior colliculus', 'Cuneiform nucleus', 'Red nucleus'], correct: 1, explanation: 'Afferents from the optic tract bypass the LGN and synapse in the pretectal nucleus, which projects bilaterally to the Edinger-Westphal nucleus.' },
  { id: 12, topic: 'Anatomy & Embryology', q: 'The cone-to-RPE cell ratio at the fovea is approximately:', options: ['1:1', '5:1', '20:1', '100:1', '1:5'], correct: 0, explanation: 'At the fovea each cone has its own RPE cell (1:1 relationship), supporting high acuity.' },
  { id: 13, topic: 'Anatomy & Embryology', q: 'Which structure crosses ABOVE the superior oblique tendon?', options: ['Superior rectus', 'Inferior oblique', 'Lateral rectus', 'Medial rectus', 'Levator palpebrae'], correct: 0, explanation: 'The superior oblique tendon passes BELOW the superior rectus to insert on the globe.' },
  { id: 14, topic: 'Anatomy & Embryology', q: 'The hyaloid artery normally regresses by:', options: ['Birth', 'Week 20 of gestation', '6 months postnatal', '1 year postnatal', '2 years postnatal'], correct: 0, explanation: 'The hyaloid artery regresses completely by birth. Persistence causes Mittendorf dot, Bergmeister papilla, or PFV.' },
  { id: 15, topic: 'Anatomy & Embryology', q: 'The macula lutea owes its yellow color to:', options: ['Melanin', 'Lipofuscin', 'Xanthophyll (lutein/zeaxanthin)', 'Hemosiderin', 'Beta-carotene'], correct: 2, explanation: 'Xanthophyll pigments (lutein and zeaxanthin) accumulate in the macula and filter blue light, protecting against oxidative damage.' },

  // ============ Optics & Refraction (20) ============
  { id: 16, topic: 'Optics & Refraction', q: 'The total refractive power of the eye is approximately:', options: ['+20 D', '+43 D', '+60 D', '+100 D', '+15 D'], correct: 2, explanation: 'The total power of the schematic eye is ~+60 D, with the cornea contributing ~+43 D and the lens ~+17–20 D.' },
  { id: 17, topic: 'Optics & Refraction', q: 'A patient with a refractive error of +3.00 DS has:', options: ['Myopia', 'Hyperopia', 'Mixed astigmatism', 'Emmetropia', 'Aphakia'], correct: 1, explanation: 'A positive sphere indicates hyperopia. Parallel light is focused behind the retina; convex lenses correct it.' },
  { id: 18, topic: 'Optics & Refraction', q: 'In with-the-rule astigmatism, the steepest meridian is:', options: ['Horizontal (180°)', 'Vertical (90°)', 'Oblique (45°)', 'Oblique (135°)', 'No fixed orientation'], correct: 1, explanation: 'With-the-rule astigmatism has the steep meridian vertical (close to 90°). It is the commonest form in young patients.' },
  { id: 19, topic: 'Optics & Refraction', q: 'The far point of an emmetropic eye is at:', options: ['25 cm', '6 metres', 'Infinity', '1 metre', 'Anterior focal point of the cornea'], correct: 2, explanation: 'In emmetropia parallel rays (from infinity) focus on the retina with accommodation relaxed; thus far point = infinity.' },
  { id: 20, topic: 'Optics & Refraction', q: 'Spherical equivalent of +2.00 / -1.00 × 90° is:', options: ['+1.00 D', '+1.50 D', '+2.50 D', '+2.00 D', '+3.00 D'], correct: 1, explanation: 'Spherical equivalent = sphere + (cylinder/2) = +2.00 + (-1.00/2) = +1.50 D.' },
  { id: 21, topic: 'Optics & Refraction', q: 'Best test for evaluating distortion in epiretinal membrane is:', options: ['Snellen acuity', 'Amsler grid', 'Ishihara plates', 'Pelli-Robson chart', 'Goldmann perimetry'], correct: 1, explanation: 'The Amsler grid is sensitive for metamorphopsia and central scotomas associated with macular pathology including ERM.' },
  { id: 22, topic: 'Optics & Refraction', q: 'A myope reads comfortably without glasses at 25 cm. What is the approximate refractive error?', options: ['-1.00 D', '-2.00 D', '-4.00 D', '-6.00 D', '-8.00 D'], correct: 2, explanation: 'A myope whose far point is at 25 cm has a refractive error of 1/0.25 = -4.00 D.' },
  { id: 23, topic: 'Optics & Refraction', q: 'IOL power calculation in eyes with prior LASIK is most accurately performed using:', options: ['SRK II', 'Hoffer Q', 'Haigis-L or Barrett True-K', 'Holladay 1', 'Regression formula'], correct: 2, explanation: 'Post-refractive surgery eyes require dedicated formulas such as Haigis-L or Barrett True-K (or the ASCRS post-refractive calculator).' },
  { id: 24, topic: 'Optics & Refraction', q: 'A "Jackson cross cylinder" is used to refine:', options: ['Sphere only', 'Cylinder power and axis', 'Add for presbyopia', 'Prism prescription', 'Pupil size'], correct: 1, explanation: 'The JCC refines both the power and axis of the cylindrical correction during subjective refraction.' },
  { id: 25, topic: 'Optics & Refraction', q: 'The accommodative amplitude in a 40-year-old is approximately (Hofstetter\'s average):', options: ['10 D', '6 D', '4.5 D', '2 D', '1 D'], correct: 2, explanation: 'Hofstetter\'s average: 18.5 − 0.3 × age = 18.5 − 12 = 6.5 D; minimum amplitude = 15 − 0.25 × age ≈ 5 D at 40. ~4.5 D is the expected minimum/average range for this option set.' },
  { id: 26, topic: 'Optics & Refraction', q: 'Image formed on the retina in a normal eye is:', options: ['Real, erect, diminished', 'Real, inverted, diminished', 'Virtual, erect, magnified', 'Real, inverted, magnified', 'Virtual, inverted, diminished'], correct: 1, explanation: 'A convex lens system (eye) forms a real, inverted, and diminished image of distant objects on the retina.' },
  { id: 27, topic: 'Optics & Refraction', q: 'In keratoconus, the earliest refractive change is typically:', options: ['Hyperopic shift', 'Increasing oblique/irregular astigmatism', 'Decreasing astigmatism', 'Anisocoria', 'Loss of color vision'], correct: 1, explanation: 'Progressive irregular astigmatism (often oblique) with steepening on topography is the earliest sign of keratoconus.' },
  { id: 28, topic: 'Optics & Refraction', q: 'The vergence of light from an object at 50 cm is:', options: ['+2 D', '-2 D', '+0.5 D', '-0.5 D', '+1 D'], correct: 1, explanation: 'Vergence = 1/distance in metres with appropriate sign. A real object at 50 cm gives -2.00 D (diverging) at the lens.' },
  { id: 29, topic: 'Optics & Refraction', q: 'A patient sees better through a pinhole. The most likely cause is:', options: ['Cortical cataract', 'Refractive error or media irregularity', 'Optic neuritis', 'Macular hole', 'Amblyopia'], correct: 1, explanation: 'Pinhole improves acuity by reducing the effect of refractive error and irregular media; little improvement in macular/neural causes.' },
  { id: 30, topic: 'Optics & Refraction', q: 'The Knapp\'s rule states that for axial ametropia, the image size is unchanged if:', options: ['Glasses worn at corneal plane', 'Glasses worn at the anterior focal point of the eye', 'Contact lens is used', 'IOL is implanted', 'Aphakic spectacles are used'], correct: 1, explanation: 'Knapp\'s rule: in axial ametropia, correcting with a lens placed at the anterior focal point of the eye (~15.7 mm in front of the cornea) produces no change in retinal image size.' },
  { id: 31, topic: 'Optics & Refraction', q: 'The principal action of cycloplegic agents in refraction is:', options: ['Pupil dilation only', 'Paralysis of accommodation', 'Lowering IOP', 'Improving fundus view', 'Producing miosis'], correct: 1, explanation: 'Cycloplegics paralyse the ciliary muscle, suspending accommodation so latent hyperopia can be measured accurately.' },
  { id: 32, topic: 'Optics & Refraction', q: 'A +10 D lens has a focal length of:', options: ['1 cm', '10 cm', '100 cm', '0.1 cm', '20 cm'], correct: 1, explanation: 'Focal length (m) = 1/power (D); 1/10 = 0.1 m = 10 cm.' },
  { id: 33, topic: 'Optics & Refraction', q: 'Anisometropia of how many dioptres typically risks amblyopia in children?', options: ['≥0.25 D', '≥1.5 D', '≥4 D', '≥6 D', '≥10 D'], correct: 1, explanation: 'Anisometropia of ~1.5 D (or 1 D hyperopic, 3 D myopic, 1.5 D astigmatic) is generally regarded as amblyogenic.' },
  { id: 34, topic: 'Optics & Refraction', q: 'In presbyopia the principal physiologic change is decreased:', options: ['Axial length', 'Lens elasticity', 'Ciliary muscle strength', 'Pupil diameter', 'Vitreous viscosity'], correct: 1, explanation: 'Presbyopia is mainly due to lens stiffening (loss of elasticity) leading to a progressive decline in accommodative amplitude.' },
  { id: 35, topic: 'Optics & Refraction', q: 'A duochrome (red-green) test uses the principle of:', options: ['Color blindness', 'Chromatic aberration of the eye', 'Polarisation', 'Stereoscopy', 'Phase difference'], correct: 1, explanation: 'The duochrome test exploits longitudinal chromatic aberration: red focuses behind, green in front of the retina. Equal clarity = correct sphere.' },

  // ============ Cornea & External Disease (20) ============
  { id: 36, topic: 'Cornea & External Disease', q: 'A dendritic ulcer staining with fluorescein in a young adult is most likely caused by:', options: ['Bacterial keratitis', 'Herpes simplex epithelial keratitis', 'Herpes zoster ophthalmicus', 'Acanthamoeba', 'Pseudomonas'], correct: 1, explanation: 'A true branching dendrite with terminal bulbs and ulcerated centre is pathognomonic of HSV epithelial keratitis. HZO produces pseudodendrites without true ulceration.' },
  { id: 37, topic: 'Cornea & External Disease', q: 'The earliest topographic sign of keratoconus is:', options: ['Diffuse flattening', 'Inferior steepening with skewed radial axes (SRAX)', 'Central island', 'Pellucid pattern', 'Symmetric bowtie'], correct: 1, explanation: 'Asymmetric inferior steepening with skewed radial axes (loss of bowtie symmetry) is the earliest topographic sign.' },
  { id: 38, topic: 'Cornea & External Disease', q: 'Munson\'s sign is associated with:', options: ['Keratoconjunctivitis sicca', 'Keratoconus', 'Pterygium', 'Acanthamoeba keratitis', 'Trachoma'], correct: 1, explanation: 'Munson\'s sign is V-shaped indentation of the lower eyelid on downgaze due to corneal protrusion in advanced keratoconus.' },
  { id: 39, topic: 'Cornea & External Disease', q: 'Endothelial cell density below which decompensation risk significantly rises:', options: ['2500/mm²', '2000/mm²', '1500/mm²', '500/mm²', '3000/mm²'], correct: 3, explanation: 'Below ~500 cells/mm² the endothelial pump fails and corneal oedema is likely. Cataract surgery is risky <1000.' },
  { id: 40, topic: 'Cornea & External Disease', q: 'The most common cause of bacterial keratitis in contact lens wearers is:', options: ['Staph aureus', 'Strep pneumoniae', 'Pseudomonas aeruginosa', 'Moraxella', 'Acanthamoeba'], correct: 2, explanation: 'Pseudomonas aeruginosa is the commonest organism in contact-lens related bacterial keratitis due to its biofilm formation.' },
  { id: 41, topic: 'Cornea & External Disease', q: 'Acanthamoeba keratitis classically presents with:', options: ['Painless ulcer with hypopyon', 'Severe pain out of proportion to signs, ring infiltrate, radial keratoneuritis', 'Dendritic ulcer', 'Hypopyon and posterior synechiae', 'Mucopurulent discharge only'], correct: 1, explanation: 'Acanthamoeba causes severe pain disproportionate to slit-lamp findings, with a characteristic ring infiltrate and radial perineural infiltrates.' },
  { id: 42, topic: 'Cornea & External Disease', q: 'A child with bilateral mucopurulent conjunctivitis and follicles on the lower tarsus may have:', options: ['Allergic conjunctivitis', 'Chlamydial trachoma', 'Viral conjunctivitis', 'Vernal keratoconjunctivitis', 'Floppy eyelid syndrome'], correct: 1, explanation: 'Trachoma (Chlamydia trachomatis serovars A-C) classically begins with mucopurulent discharge and follicles on the superior tarsus in endemic regions.' },
  { id: 43, topic: 'Cornea & External Disease', q: 'The most specific corneal dystrophy associated with TGFBI gene mutation is:', options: ['Fuchs endothelial', 'Lattice (LCD1)', 'Posterior polymorphous', 'Meesmann', 'Schnyder'], correct: 1, explanation: 'TGFBI mutations cause Lattice (type 1), Granular, Avellino, and Reis-Bückler dystrophies. Lattice type 2 (Meretoja) involves the gelsolin gene.' },
  { id: 44, topic: 'Cornea & External Disease', q: 'Kayser-Fleischer ring is found in:', options: ['Hemochromatosis', 'Wilson\'s disease', 'Lowe syndrome', 'Cystinosis', 'Marfan syndrome'], correct: 1, explanation: 'Kayser-Fleischer ring is a copper deposition in Descemet\'s membrane (Wilson\'s disease) and is best seen on gonioscopy.' },
  { id: 45, topic: 'Cornea & External Disease', q: 'Most appropriate first-line treatment for herpes simplex epithelial dendritic keratitis is:', options: ['Topical corticosteroid', 'Topical ganciclovir 0.15% gel or trifluridine', 'Oral cephalexin', 'Topical NSAID', 'Bandage contact lens alone'], correct: 1, explanation: 'Topical antiviral (ganciclovir 0.15% gel, trifluridine 1%) ± oral acyclovir/valacyclovir is first line. Steroids worsen epithelial disease.' },
  { id: 46, topic: 'Cornea & External Disease', q: 'Vernal keratoconjunctivitis is best characterised by:', options: ['Bulbar follicles', 'Giant papillae on upper tarsus + Horner-Trantas dots', 'Marginal infiltrates', 'Mucopurulent discharge', 'Pre-auricular lymphadenopathy'], correct: 1, explanation: 'VKC presents in young atopic patients with cobblestone papillae on the upper tarsus and limbal Horner-Trantas dots.' },
  { id: 47, topic: 'Cornea & External Disease', q: 'Hudson-Stähli line is:', options: ['Iron deposition in corneal epithelium at the lower one-third', 'Hemosiderin in stroma', 'Calcium in Bowman layer', 'Copper in Descemet', 'Cholesterol in stroma'], correct: 0, explanation: 'A horizontal brown line of iron deposition in the inferior corneal epithelium, increasing with age. Other iron lines: Fleischer (keratoconus), Stocker (pterygium), Ferry (filtering bleb).' },
  { id: 48, topic: 'Cornea & External Disease', q: 'Recommended preferred treatment for moderate-severe Fuchs endothelial dystrophy with cataract:', options: ['Phacoemulsification only', 'PKP alone', 'Combined phaco + DMEK / DSAEK', 'Conservative management with hypertonic saline', 'Laser photocoagulation'], correct: 2, explanation: 'When stromal oedema is present, combined phaco with DMEK (preferred) or DSAEK gives best functional results.' },
  { id: 49, topic: 'Cornea & External Disease', q: 'Schirmer\'s test with anaesthesia measuring <5 mm in 5 minutes indicates:', options: ['Normal tear secretion', 'Mild dry eye', 'Severe aqueous deficient dry eye', 'Mucin deficiency', 'Reflex tearing'], correct: 2, explanation: 'Schirmer I with anaesthesia <5 mm/5 min indicates severe aqueous-deficient dry eye (basal secretion measurement).' },
  { id: 50, topic: 'Cornea & External Disease', q: 'Most common cause of fungal keratitis in tropical/agricultural settings is:', options: ['Candida albicans', 'Fusarium spp.', 'Aspergillus', 'Cryptococcus', 'Rhizopus'], correct: 1, explanation: 'Fusarium is the commonest filamentous fungus in tropical regions (often after vegetative trauma); Aspergillus is next. Candida predominates in compromised hosts.' },
  { id: 51, topic: 'Cornea & External Disease', q: 'The corneal layer most resistant to bending forces and contributing most to mechanical strength is:', options: ['Epithelium', 'Bowman layer', 'Stroma', 'Descemet membrane', 'Endothelium'], correct: 2, explanation: 'The stroma accounts for ~90 % of corneal thickness and provides most of the cornea\'s tensile strength via collagen lamellae.' },
  { id: 52, topic: 'Cornea & External Disease', q: 'Cogan microcystic epithelial dystrophy (EBMD) is characterised by:', options: ['Maps, dots, fingerprints in epithelium', 'Endothelial guttata', 'Stromal lattice lines', 'Subepithelial calcification', 'Iron deposition'], correct: 0, explanation: 'EBMD shows map-dot-fingerprint changes from abnormal epithelial basement membrane, commonly causing recurrent erosions.' },
  { id: 53, topic: 'Cornea & External Disease', q: 'Pseudomembranes are typical of which conjunctivitis:', options: ['Allergic', 'Viral (adenoviral) and severe bacterial (e.g. diphtheria)', 'Toxic', 'Chemical splash', 'Chronic blepharitis'], correct: 1, explanation: 'Pseudomembranes and true membranes occur in severe adenoviral conjunctivitis, gonococcal, diphtheric, and Stevens-Johnson conjunctivitis.' },
  { id: 54, topic: 'Cornea & External Disease', q: 'In suspected ocular surface chemical injury, the first intervention is:', options: ['Apply antibiotic ointment', 'Immediate copious irrigation', 'Refer to ophthalmology', 'Pressure patch', 'Topical steroid'], correct: 1, explanation: 'Immediate prolonged irrigation with saline/Ringer\'s lactate (or water) for at least 15-30 minutes is the single most important step; check pH after.' },
  { id: 55, topic: 'Cornea & External Disease', q: 'Pterygium classically grows:', options: ['Superiorly from the cornea', 'From temporal limbus', 'From nasal limbus toward visual axis', 'Around the entire limbus', 'Only on the inferior conjunctiva'], correct: 2, explanation: 'Pterygium is a triangular fibrovascular growth typically arising from the nasal interpalpebral conjunctiva and encroaching onto the cornea.' },

  // ============ Lens & Cataract (15) ============
  { id: 56, topic: 'Lens & Cataract', q: 'Posterior subcapsular cataract is MOST classically associated with:', options: ['Diabetes only', 'Chronic corticosteroid use', 'Galactosemia', 'Hypocalcemia', 'Hyperthyroidism'], correct: 1, explanation: 'PSC is the hallmark of chronic systemic or topical steroid therapy; it also occurs with radiation, uveitis, and high myopia.' },
  { id: 57, topic: 'Lens & Cataract', q: '"Christmas tree" cataract is characteristic of:', options: ['Diabetes', 'Myotonic dystrophy', 'Atopic dermatitis', 'Wilson disease', 'Galactosemia'], correct: 1, explanation: 'Polychromatic iridescent crystals in the cortex ("Christmas tree" cataract) are characteristic of myotonic dystrophy.' },
  { id: 58, topic: 'Lens & Cataract', q: 'In sunflower cataract, the deposited substance is:', options: ['Copper', 'Iron', 'Silver', 'Calcium', 'Mercury'], correct: 0, explanation: 'Sunflower cataract is copper deposition under the anterior lens capsule in Wilson\'s disease or chalcosis.' },
  { id: 59, topic: 'Lens & Cataract', q: 'Phacoanaphylactic uveitis is caused by:', options: ['Type I hypersensitivity to lens proteins', 'Granulomatous reaction to retained lens material', 'Bacterial endophthalmitis', 'Sympathetic ophthalmia', 'Allergy to viscoelastic'], correct: 1, explanation: 'Phacoanaphylactic (lens-induced granulomatous) uveitis is a zonal granulomatous reaction to lens proteins after capsule disruption.' },
  { id: 60, topic: 'Lens & Cataract', q: 'Most common indication for YAG capsulotomy:', options: ['Vitreous opacities', 'Posterior capsular opacification', 'Pupillary block', 'IOL repositioning', 'Cyclodialysis cleft'], correct: 1, explanation: 'YAG laser capsulotomy is performed for visually significant posterior capsular opacification (PCO) after cataract surgery.' },
  { id: 61, topic: 'Lens & Cataract', q: 'Risk factor LEAST associated with intra-operative floppy iris syndrome (IFIS):', options: ['Tamsulosin', 'Other α-1A antagonists', 'Topical pilocarpine pre-op', 'Finasteride alone', 'Saw palmetto extract'], correct: 3, explanation: 'IFIS is strongly associated with α-1A antagonists (notably tamsulosin); finasteride (5α-reductase inhibitor) alone is not a recognised cause.' },
  { id: 62, topic: 'Lens & Cataract', q: 'Soemmering ring describes:', options: ['Subluxated lens', 'Doughnut-shaped peripheral residual lens cortex after rupture/surgery', 'Pigment ring on lens', 'Anterior capsule fibrosis', 'Ciliary body cyst'], correct: 1, explanation: 'Soemmering ring is residual peripheral cortex sandwiched between the anterior and posterior capsules after rupture or extracapsular extraction.' },
  { id: 63, topic: 'Lens & Cataract', q: 'In congenital cataract surgery the recommended optical timing for visually significant unilateral cataract is:', options: ['Within 6 weeks of birth', 'Around 6 months', 'At 1 year', 'At 2 years', 'Defer to age 3'], correct: 0, explanation: 'Dense unilateral congenital cataract should be removed before 6 weeks of age to prevent dense deprivational amblyopia.' },
  { id: 64, topic: 'Lens & Cataract', q: 'Phacoemulsification using ultrasound at 28 kHz works by:', options: ['Heating tissue to vaporise it', 'Mechanical jackhammer and cavitation', 'Direct laser ablation', 'Cryocoagulation', 'Chemical dissolution'], correct: 1, explanation: 'Phaco needles oscillate at ~28-40 kHz, producing mechanical impact and cavitation that emulsify the lens nucleus.' },
  { id: 65, topic: 'Lens & Cataract', q: 'In ectopia lentis associated with Marfan syndrome, displacement is classically:', options: ['Infero-nasal', 'Supero-temporal', 'Posterior', 'Anterior chamber', 'No fixed pattern'], correct: 1, explanation: 'Marfan: supero-temporal displacement. Homocystinuria: infero-nasal. Weill-Marchesani: microspherophakia with subluxation.' },
  { id: 66, topic: 'Lens & Cataract', q: 'Refractive shift in nuclear sclerosis is typically:', options: ['Hyperopic', 'Myopic ("second sight")', 'Astigmatic only', 'No change', 'Aniseikonia'], correct: 1, explanation: 'Increased refractive index of nuclear sclerotic lens causes a myopic shift, sometimes letting presbyopes read without glasses ("second sight").' },
  { id: 67, topic: 'Lens & Cataract', q: 'Most common cause of late IOL dislocation 10+ years after uneventful phaco:', options: ['Trauma', 'Pseudoexfoliation', 'Capsular block', 'PCO contraction alone', 'High myopia alone'], correct: 1, explanation: 'Pseudoexfoliation syndrome with progressive zonular weakness is the commonest cause of late spontaneous IOL-bag dislocation.' },
  { id: 68, topic: 'Lens & Cataract', q: 'Best treatment for postoperative cystoid macular oedema (Irvine-Gass):', options: ['Observation only', 'Topical NSAID + steroid combination', 'Anti-VEGF first line', 'Pars plana vitrectomy', 'Subconjunctival 5-FU'], correct: 1, explanation: 'First-line therapy for Irvine-Gass CME is topical NSAIDs combined with topical corticosteroids; refractory cases may need intravitreal steroid or anti-VEGF.' },
  { id: 69, topic: 'Lens & Cataract', q: 'A lens-induced glaucoma with hypermature cataract leaking proteins is termed:', options: ['Phacomorphic glaucoma', 'Phacolytic glaucoma', 'Phacoanaphylactic glaucoma', 'Phacoantigenic uveitis', 'Phacoblock'], correct: 1, explanation: 'Phacolytic glaucoma is open-angle glaucoma due to leakage of high-molecular-weight lens proteins through an intact capsule of a hypermature lens.' },
  { id: 70, topic: 'Lens & Cataract', q: 'In intraoperative posterior capsule rupture without vitreous loss, the most important next step is:', options: ['Convert to extracapsular extraction', 'Inject viscoelastic to tamponade and carefully remove residual cortex', 'Suture incision and refer', 'Abort surgery', 'Aggressive irrigation to remove cortex'], correct: 1, explanation: 'Injecting dispersive viscoelastic to tamponade vitreous and stabilise the rupture allows controlled cortex removal; avoid aggressive irrigation/aspiration over a tear.' },

  // ============ Glaucoma (20) ============
  { id: 71, topic: 'Glaucoma', q: 'In primary open-angle glaucoma the most reliable structural test for early damage is:', options: ['Gonioscopy', 'Optical coherence tomography of RNFL/GCC', 'Tonometry', 'Specular microscopy', 'Pachymetry'], correct: 1, explanation: 'OCT of the peripapillary RNFL and macular ganglion cell complex detects structural loss earlier than visual field defects in POAG.' },
  { id: 72, topic: 'Glaucoma', q: 'Classic visual field defect in glaucoma:', options: ['Central scotoma', 'Bitemporal hemianopia', 'Arcuate scotoma respecting horizontal meridian', 'Junctional scotoma', 'Altitudinal defect'], correct: 2, explanation: 'Glaucomatous field loss follows the arcuate nerve fibre pattern and respects the horizontal meridian (nasal step, arcuate, Bjerrum scotoma).' },
  { id: 73, topic: 'Glaucoma', q: 'First-line medical therapy for primary open-angle glaucoma:', options: ['Topical beta-blocker', 'Topical prostaglandin analogue', 'Oral acetazolamide', 'Pilocarpine', 'Brimonidine'], correct: 1, explanation: 'Prostaglandin analogues (latanoprost, travoprost, bimatoprost, tafluprost) are first-line for POAG: best IOP lowering, once-daily dosing, few systemic effects.' },
  { id: 74, topic: 'Glaucoma', q: 'A central corneal thickness of 480 μm in a glaucoma suspect implies:', options: ['Underestimation of true IOP', 'Overestimation of true IOP', 'No effect on IOP reading', 'Always indicates keratoconus', 'Requires immediate trabeculectomy'], correct: 0, explanation: 'Thin corneas (<555 μm) lead to underestimation of true IOP with Goldmann and are an independent risk factor for glaucoma progression (OHTS).' },
  { id: 75, topic: 'Glaucoma', q: 'Acute primary angle closure crisis: emergency treatment of choice:', options: ['Immediate trabeculectomy', 'Topical pilocarpine 2% + IOP-lowering medical Rx + later laser PI', 'Laser trabeculoplasty', 'Cyclophotocoagulation', 'Topical steroid only'], correct: 1, explanation: 'Initial treatment is medical IOP lowering (timolol, brimonidine, acetazolamide, hyperosmotic) plus pilocarpine after pressure drops, then laser PI once cornea clears.' },
  { id: 76, topic: 'Glaucoma', q: 'Pigment dispersion syndrome classically affects:', options: ['Elderly hyperopes', 'Young myopic males', 'Postmenopausal women', 'Diabetics', 'Children'], correct: 1, explanation: 'PDS classically occurs in young (20-40 y) myopic males with Krukenberg spindle, mid-peripheral iris transillumination and pigment in the trabecular meshwork.' },
  { id: 77, topic: 'Glaucoma', q: 'Pseudoexfoliation material is best seen on:', options: ['Anterior lens capsule and pupillary margin', 'Posterior capsule', 'Iris stroma surface', 'Cornea endothelium', 'Optic disc'], correct: 0, explanation: 'PXF deposits classically appear on the anterior lens capsule (central disc, peripheral band, clear intermediate zone) and at the pupillary margin.' },
  { id: 78, topic: 'Glaucoma', q: 'In neovascular glaucoma the rate-limiting management step is:', options: ['Cyclodestruction first', 'Treat underlying ischemia (PRP ± anti-VEGF)', 'Trabeculectomy with MMC immediately', 'Topical β-blockers only', 'Iridotomy'], correct: 1, explanation: 'NVG must be treated by addressing the underlying retinal ischemia (PRP) and acutely with anti-VEGF; IOP-lowering surgery is needed only after vascularisation is regressed.' },
  { id: 79, topic: 'Glaucoma', q: 'Trabeculectomy with mitomycin C primarily acts to:', options: ['Increase uveoscleral outflow', 'Prevent subconjunctival fibrosis improving bleb survival', 'Inhibit aqueous formation', 'Promote angle widening', 'Strengthen the trabecular meshwork'], correct: 1, explanation: 'Intraoperative MMC inhibits fibroblast proliferation, reducing scarring at the bleb site and improving long-term IOP control.' },
  { id: 80, topic: 'Glaucoma', q: 'The most accurate office method to assess angle structures is:', options: ['Penlight Van Herick test', 'Goldmann gonioscopy / anterior segment OCT', 'Slit lamp without contact', 'Fundoscopy', 'Ultrasonography B-scan'], correct: 1, explanation: 'Gonioscopy (Goldmann or Posner) is the gold standard for angle assessment; anterior-segment OCT and UBM are useful adjuncts.' },
  { id: 81, topic: 'Glaucoma', q: 'Aqueous humour is produced by:', options: ['Pigmented ciliary epithelium', 'Non-pigmented ciliary epithelium', 'Trabecular meshwork', 'Endothelium', 'Iris stroma'], correct: 1, explanation: 'Non-pigmented ciliary epithelium of the pars plicata produces aqueous via active secretion involving Na⁺/K⁺-ATPase and carbonic anhydrase.' },
  { id: 82, topic: 'Glaucoma', q: 'The drug class that lowers IOP by reducing aqueous production AND increasing uveoscleral outflow:', options: ['Beta-blocker', 'Alpha-2 agonist (e.g. brimonidine)', 'Prostaglandin analogue', 'Pilocarpine', 'Carbonic anhydrase inhibitor'], correct: 1, explanation: 'Alpha-2 agonists like brimonidine both reduce aqueous formation and enhance uveoscleral outflow.' },
  { id: 83, topic: 'Glaucoma', q: 'A patient with optic-disc cupping 0.9, IOP 14, normal visual field, family history of POAG. Likely diagnosis:', options: ['Normal-tension glaucoma', 'Physiologic cupping', 'Optic neuropathy', 'Pseudoexfoliative glaucoma', 'Steroid-induced glaucoma'], correct: 0, explanation: 'Normal-tension glaucoma: glaucomatous optic neuropathy with IOP consistently ≤21 mmHg; family history and disc haemorrhages are risk factors.' },
  { id: 84, topic: 'Glaucoma', q: 'Acetazolamide acts by inhibiting carbonic anhydrase isoenzyme:', options: ['CA-I', 'CA-II', 'CA-IV', 'CA-IX', 'CA-XII'], correct: 1, explanation: 'CA-II in the ciliary epithelium is the major isoenzyme inhibited to reduce bicarbonate (and hence aqueous) secretion.' },
  { id: 85, topic: 'Glaucoma', q: 'Plateau iris configuration features:', options: ['Pupillary block as main mechanism', 'Anteriorly positioned ciliary processes causing peripheral iris bunching', 'Dense iris pigmentation', 'Subluxated lens', 'Iris atrophy'], correct: 1, explanation: 'Plateau iris is caused by anteriorly positioned ciliary processes that push the peripheral iris forward despite a patent iridotomy; treated with argon laser iridoplasty.' },
  { id: 86, topic: 'Glaucoma', q: 'Most common cause of secondary open-angle glaucoma worldwide:', options: ['Pigment dispersion', 'Pseudoexfoliation', 'Inflammatory', 'Steroid response', 'Phacolytic'], correct: 1, explanation: 'Pseudoexfoliation is the commonest identifiable cause of secondary open-angle glaucoma worldwide, with higher IOP fluctuations and faster progression.' },
  { id: 87, topic: 'Glaucoma', q: 'Selective laser trabeculoplasty (SLT) targets:', options: ['Schlemm canal', 'Pigmented trabecular meshwork cells (selective melanin absorption)', 'Ciliary body', 'Iris stroma', 'Sclera'], correct: 1, explanation: 'SLT uses a frequency-doubled Q-switched Nd:YAG (532 nm) selectively absorbed by pigmented TM cells without collateral thermal damage.' },
  { id: 88, topic: 'Glaucoma', q: 'Optic disc haemorrhage (Drance) is most ominous because it:', options: ['Indicates active inflammation', 'Predicts future field progression in glaucoma', 'Suggests papilloedema', 'Is benign and self-resolving', 'Indicates BRVO'], correct: 1, explanation: 'A Drance haemorrhage at the disc margin is a strong independent predictor of progressive glaucomatous damage.' },
  { id: 89, topic: 'Glaucoma', q: 'Primary congenital glaucoma classic triad:', options: ['Photophobia, epiphora, blepharospasm', 'Leukocoria, strabismus, nystagmus', 'Cataract, glaucoma, deafness', 'Buphthalmos, microcornea, cataract', 'Heterochromia, ptosis, miosis'], correct: 0, explanation: 'Primary congenital glaucoma presents with photophobia, epiphora and blepharospasm; signs include corneal oedema, Haab striae, buphthalmos.' },
  { id: 90, topic: 'Glaucoma', q: 'Most common type of glaucoma in Asians:', options: ['Primary open-angle', 'Primary angle-closure', 'Pseudoexfoliative', 'Neovascular', 'Pigmentary'], correct: 1, explanation: 'In East and South Asian populations primary angle-closure disease accounts for a major share of glaucoma blindness due to anatomically narrower anterior chambers.' },

  // ============ Uveitis (15) ============
  { id: 91, topic: 'Uveitis', q: 'Hypopyon uveitis is characteristic of:', options: ['Toxoplasmosis', 'HLA-B27 associated anterior uveitis and Behçet disease', 'Sarcoidosis', 'Fuchs heterochromic uveitis', 'CMV retinitis'], correct: 1, explanation: 'Hypopyon is classically seen in HLA-B27 acute anterior uveitis and Behçet disease; rarely in infections and endophthalmitis.' },
  { id: 92, topic: 'Uveitis', q: 'Fuchs heterochromic iridocyclitis is characterised by:', options: ['Granulomatous uveitis with posterior synechiae', 'Mild chronic anterior uveitis WITHOUT synechiae, heterochromia, secondary cataract', 'Acute hypopyon uveitis', 'Necrotising retinitis', 'Vasculitis'], correct: 1, explanation: 'Fuchs is a low-grade chronic anterior uveitis classically with heterochromia, fine stellate KPs, absence of posterior synechiae, cataract and secondary glaucoma.' },
  { id: 93, topic: 'Uveitis', q: 'Mutton-fat keratic precipitates indicate:', options: ['Non-granulomatous uveitis', 'Granulomatous uveitis (e.g. sarcoid, TB, syphilis, VKH)', 'Infectious endophthalmitis', 'Pigment dispersion', 'Iridoschisis'], correct: 1, explanation: 'Large greasy mutton-fat KPs (made of epithelioid cells) signify granulomatous inflammation – sarcoidosis, TB, syphilis, VKH, sympathetic ophthalmia.' },
  { id: 94, topic: 'Uveitis', q: 'Vogt-Koyanagi-Harada syndrome classically involves:', options: ['Vasculitic retinitis only', 'Bilateral panuveitis with serous retinal detachments, meningism, vitiligo, poliosis', 'Granulomatous keratitis', 'Anterior segment only', 'Endophthalmitis'], correct: 1, explanation: 'VKH is an autoimmune disease against melanocytes causing bilateral granulomatous panuveitis with exudative RDs, plus auditory, meningeal, integumentary signs.' },
  { id: 95, topic: 'Uveitis', q: 'Posterior synechiae predispose to:', options: ['Hyphema', 'Iris bombe and angle closure', 'Choroidal effusion', 'Macular hole', 'Vitreous haemorrhage'], correct: 1, explanation: 'Posterior synechiae block aqueous flow through the pupil leading to iris bombe and secondary angle closure.' },
  { id: 96, topic: 'Uveitis', q: 'Most common cause of posterior uveitis worldwide:', options: ['Sarcoidosis', 'Toxoplasmosis', 'Behçet disease', 'CMV', 'Syphilis'], correct: 1, explanation: 'Toxoplasma chorioretinitis is the leading cause of posterior uveitis worldwide; classic appearance is a focal necrotising retinitis adjacent to an old pigmented scar.' },
  { id: 97, topic: 'Uveitis', q: 'CMV retinitis typically occurs when CD4 count drops below:', options: ['500', '350', '200', '50', '1000'], correct: 3, explanation: 'CMV retinitis is an AIDS-defining illness usually occurring with CD4 < 50/μL.' },
  { id: 98, topic: 'Uveitis', q: 'Acute retinal necrosis (ARN) is most commonly caused by:', options: ['Toxoplasma', 'Herpes simplex / varicella zoster virus', 'CMV', 'Tuberculosis', 'Treponema'], correct: 1, explanation: 'ARN is typically due to VZV or HSV, presenting with peripheral necrotising retinitis, retinal vasculitis, vitritis and a high rate of detachment.' },
  { id: 99, topic: 'Uveitis', q: 'Sympathetic ophthalmia is:', options: ['Hereditary uveitis', 'Bilateral granulomatous panuveitis after penetrating trauma/surgery to one eye', 'Photosensitive dermatitis', 'Drug reaction', 'Tumour related'], correct: 1, explanation: 'Sympathetic ophthalmia is a delayed bilateral granulomatous panuveitis following penetrating injury or intraocular surgery to a fellow ("exciting") eye.' },
  { id: 100, topic: 'Uveitis', q: 'First-line steroid-sparing agent for chronic non-infectious uveitis:', options: ['Cyclophosphamide', 'Methotrexate', 'Mycophenolate or azathioprine', 'IVIG', 'Rituximab'], correct: 2, explanation: 'Methotrexate, mycophenolate mofetil and azathioprine are common first-line steroid-sparing immunomodulators in non-infectious uveitis.' },
  { id: 101, topic: 'Uveitis', q: 'Pars planitis primarily affects:', options: ['Elderly women', 'Children and young adults with snowballs/snowbanks in inferior peripheral vitreous', 'Diabetics', 'Patients with HIV', 'Postoperative patients'], correct: 1, explanation: 'Pars planitis is a chronic intermediate uveitis predominantly in children/young adults with vitreous "snowballs" and inferior snowbanking; associated with MS.' },
  { id: 102, topic: 'Uveitis', q: 'Most common ocular manifestation of sarcoidosis:', options: ['Posterior uveitis', 'Granulomatous anterior uveitis', 'Optic neuropathy', 'Scleritis', 'Conjunctival nodule'], correct: 1, explanation: 'Granulomatous anterior uveitis is the commonest ocular involvement in sarcoidosis, often with mutton-fat KPs and iris nodules.' },
  { id: 103, topic: 'Uveitis', q: 'Behçet disease ocular features include:', options: ['Granulomatous anterior uveitis only', 'Recurrent non-granulomatous panuveitis with retinal vasculitis and hypopyon', 'Scleritis only', 'Episcleritis only', 'Marginal keratitis'], correct: 1, explanation: 'Behçet causes recurrent attacks of bilateral non-granulomatous panuveitis with occlusive retinal vasculitis and shifting hypopyon.' },
  { id: 104, topic: 'Uveitis', q: 'Treatment of choice for ocular toxoplasmosis threatening macula:', options: ['Observation', 'Oral pyrimethamine + sulfadiazine + folinic acid (or trimethoprim-sulfa) ± steroid', 'IV acyclovir', 'Cycloplegic alone', 'Intravitreal anti-VEGF'], correct: 1, explanation: 'Macula-threatening or vision-threatening lesions require classic triple therapy (pyrimethamine + sulfadiazine + folinic acid) or alternative regimens; corticosteroids added after antimicrobial onset.' },
  { id: 105, topic: 'Uveitis', q: 'Most useful single investigation in suspected ocular tuberculosis:', options: ['Mantoux test alone', 'Interferon gamma release assay (IGRA / QuantiFERON)', 'ESR', 'ANA', 'Chest X-ray alone'], correct: 1, explanation: 'IGRA (QuantiFERON-TB Gold) is specific for TB infection and unaffected by BCG vaccination; combined with chest imaging and ocular features it supports diagnosis.' },

  // ============ Retina & Vitreous (25) ============
  { id: 106, topic: 'Retina & Vitreous', q: 'Earliest sign of diabetic retinopathy is:', options: ['Hard exudates', 'Microaneurysms', 'Neovascularisation', 'Cotton-wool spots', 'Retinal detachment'], correct: 1, explanation: 'Microaneurysms (small saccular outpouchings of capillaries) are the earliest visible sign of non-proliferative diabetic retinopathy.' },
  { id: 107, topic: 'Retina & Vitreous', q: 'High-risk PDR per ETDRS criteria includes NVD ≥1/4–1/3 disc area OR:', options: ['Any vitreous haemorrhage', 'NVE with vitreous or pre-retinal haemorrhage', 'Microaneurysms only', 'Hard exudates', 'Cotton-wool spots ≥4'], correct: 1, explanation: 'High-risk PDR: NVD ≥1/4–1/3 disc area, OR any NVD with VH/preretinal haemorrhage, OR NVE ≥1/2 disc area with VH/preretinal haemorrhage.' },
  { id: 108, topic: 'Retina & Vitreous', q: 'First-line treatment for centre-involving DME with vision 6/12 or worse:', options: ['Focal laser', 'Pan-retinal photocoagulation', 'Intravitreal anti-VEGF', 'Sub-tenon triamcinolone', 'Pars plana vitrectomy'], correct: 2, explanation: 'Per DRCR.net Protocols T/V, intravitreal anti-VEGF is first-line for centre-involving DME with decreased vision. Laser remains an option for selected non-centre or refractory eyes.' },
  { id: 109, topic: 'Retina & Vitreous', q: 'Sudden painless monocular loss of vision with a cherry-red spot is most consistent with:', options: ['Central retinal vein occlusion', 'Central retinal artery occlusion', 'Vitreous haemorrhage', 'Optic neuritis', 'AION'], correct: 1, explanation: 'CRAO causes acute painless severe vision loss with a pale ischemic retina and cherry-red spot (intact foveal choroidal perfusion).' },
  { id: 110, topic: 'Retina & Vitreous', q: 'Cherry-red spot in a child with hepatosplenomegaly suggests:', options: ['Tay-Sachs disease', 'Wilson disease', 'Galactosemia', 'Hurler syndrome', 'Lowe syndrome'], correct: 0, explanation: 'Cherry-red spot in storage disorders: Tay-Sachs (no organomegaly classically), Sandhoff, Niemann-Pick. With hepatosplenomegaly think Niemann-Pick / Sandhoff; among options Tay-Sachs is the classic association.' },
  { id: 111, topic: 'Retina & Vitreous', q: 'Roth spots are:', options: ['Pigmented choroidal nevi', 'White-centred retinal haemorrhages seen in bacterial endocarditis, leukemia, anaemia', 'Yellow vitelliform lesions', 'Macular pucker', 'Drusen'], correct: 1, explanation: 'Roth spots are flame-shaped haemorrhages with central pale (white) areas. Causes: endocarditis, leukemia, severe anaemia, diabetes, HIV.' },
  { id: 112, topic: 'Retina & Vitreous', q: 'Most useful imaging for an early macular hole:', options: ['Colour fundus photo', 'Spectral-domain OCT', 'Fluorescein angiography', 'B-scan', 'OCT-angiography'], correct: 1, explanation: 'SD-OCT shows the foveal architecture and is the gold standard to stage and follow macular holes (Gass / IVTS classifications).' },
  { id: 113, topic: 'Retina & Vitreous', q: 'A 60-year-old with sudden flashes, floaters, and a curtain of vision loss most likely has:', options: ['Migraine aura', 'Posterior vitreous detachment with retinal tear/RD', 'Optic neuritis', 'AION', 'CRVO'], correct: 1, explanation: 'Flashes (photopsia) and a sudden shower of floaters in an older adult should prompt urgent retinal examination to rule out PVD with retinal tear or rhegmatogenous detachment.' },
  { id: 114, topic: 'Retina & Vitreous', q: 'Most common type of age-related macular degeneration:', options: ['Wet (neovascular)', 'Dry (non-exudative atrophic)', 'Polypoidal choroidal vasculopathy', 'Pattern dystrophy', 'Best disease'], correct: 1, explanation: 'Dry AMD (drusen ± geographic atrophy) accounts for ~85-90% of cases; wet AMD causes most severe vision loss.' },
  { id: 115, topic: 'Retina & Vitreous', q: 'Most common cause of vitreous haemorrhage in adults in developed countries:', options: ['Proliferative diabetic retinopathy', 'Retinal vein occlusion', 'PVD with retinal tear', 'Trauma', 'Sickle cell retinopathy'], correct: 0, explanation: 'PDR is the leading cause of vitreous haemorrhage in adults; PVD-related tear is the commonest non-diabetic cause.' },
  { id: 116, topic: 'Retina & Vitreous', q: 'Anti-VEGF agents act primarily by:', options: ['Photocoagulating neovascular tissue', 'Blocking VEGF-A reducing leak and neovascularisation', 'Inhibiting prostaglandins', 'Decreasing IOP', 'Inducing apoptosis of RPE'], correct: 1, explanation: 'Aflibercept, ranibizumab, bevacizumab and brolucizumab bind VEGF-A (aflibercept also VEGF-B and PlGF), reducing vascular leak and neovascularisation.' },
  { id: 117, topic: 'Retina & Vitreous', q: 'In sickle cell retinopathy, sea fan neovascularisation appears:', options: ['Posterior pole', 'Peripheral retina (mid- and far-periphery)', 'On the disc only', 'Macula only', 'Inside vitreous base'], correct: 1, explanation: 'Sea fans are characteristic peripheral neovascular tufts in proliferative sickle retinopathy (Goldberg stage III), usually treated with scatter laser if progressive.' },
  { id: 118, topic: 'Retina & Vitreous', q: 'Best disease (vitelliform dystrophy) shows on EOG:', options: ['Normal Arden ratio', 'Reduced light peak / dark trough ratio (Arden <1.5)', 'Increased ratio', 'Extinguished b-wave on ERG', 'Hyperintense on FAF only'], correct: 1, explanation: 'Best disease shows a markedly reduced Arden ratio (<1.5) on EOG, with normal full-field ERG.' },
  { id: 119, topic: 'Retina & Vitreous', q: 'Retinitis pigmentosa typically presents with:', options: ['Sudden central vision loss', 'Nyctalopia followed by progressive peripheral field loss', 'Painful red eye', 'Acute photopsia and curtain', 'Diplopia'], correct: 1, explanation: 'RP: progressive rod-cone dystrophy presenting with night blindness, ring scotoma, bone-spicule pigmentation, and ultimately tunnel vision.' },
  { id: 120, topic: 'Retina & Vitreous', q: 'Coats disease classically presents in:', options: ['Elderly women', 'Young boys with unilateral telangiectasias and exudative retinal detachment', 'Bilateral leukocoria in infants', 'Adults with hypertension', 'Premature neonates'], correct: 1, explanation: 'Coats: unilateral idiopathic retinal telangiectasias causing massive exudation and detachment, predominantly in young males.' },
  { id: 121, topic: 'Retina & Vitreous', q: 'Most common malignant intraocular tumour in adults:', options: ['Choroidal naevus', 'Choroidal melanoma', 'Metastatic carcinoma to the choroid', 'Retinoblastoma', 'Lymphoma'], correct: 2, explanation: 'Metastatic carcinoma (commonly breast in women, lung in men) is the most common malignant intraocular tumour in adults; melanoma is the commonest primary.' },
  { id: 122, topic: 'Retina & Vitreous', q: 'Photoreceptor type primarily responsible for scotopic vision:', options: ['Cones', 'Rods', 'Bipolar cells', 'Müller cells', 'Horizontal cells'], correct: 1, explanation: 'Rods (containing rhodopsin) mediate vision in low light (scotopic); cones mediate photopic and colour vision.' },
  { id: 123, topic: 'Retina & Vitreous', q: 'The retinal pigment epithelium is critical for:', options: ['Image inversion', 'Phagocytosis of photoreceptor outer segments and visual cycle', 'Conducting nerve impulses', 'Producing aqueous humour', 'Detecting light'], correct: 1, explanation: 'RPE functions include phagocytosis of shed outer segments, vitamin A retinoid (visual cycle) recycling, ion/fluid transport and blood-retinal barrier.' },
  { id: 124, topic: 'Retina & Vitreous', q: 'Most common cause of central retinal vein occlusion in elderly:', options: ['Hypercoagulable state', 'Hypertension and arteriosclerosis', 'Sickle cell disease', 'OCP use', 'Behçet disease'], correct: 1, explanation: 'Systemic hypertension and arteriosclerotic compression of the central retinal vein at the lamina cribrosa are the leading risk factors for CRVO in the elderly.' },
  { id: 125, topic: 'Retina & Vitreous', q: 'Frosted branch angiitis is associated with:', options: ['Glaucoma', 'CMV retinitis and other viral/inflammatory etiologies', 'Pterygium', 'Cataract', 'AMD'], correct: 1, explanation: 'Frosted branch angiitis presents as dramatic perivascular sheathing; associated with CMV (especially HIV), Behçet, leukemia, lymphoma and idiopathic.' },
  { id: 126, topic: 'Retina & Vitreous', q: 'Treatment for stage 3 zone II ROP with plus disease:', options: ['Observation', 'Anti-VEGF and/or laser ablation of the avascular peripheral retina', 'Scleral buckle immediately', 'Cyclocryotherapy', 'Vitrectomy first'], correct: 1, explanation: 'Type 1 ROP (per ETROP) is treated with laser ablation of the peripheral avascular retina; intravitreal anti-VEGF (e.g. bevacizumab) is an effective alternative especially for zone I disease.' },
  { id: 127, topic: 'Retina & Vitreous', q: 'Central serous chorioretinopathy classically affects:', options: ['Postmenopausal women', 'Young/middle-aged males ("type A" personality, steroid users)', 'Children', 'Diabetics primarily', 'HIV patients'], correct: 1, explanation: 'CSCR predominantly affects men 20-50 years; risk factors include type A personality, glucocorticoid use, sleep apnea, pregnancy, and Cushing syndrome.' },
  { id: 128, topic: 'Retina & Vitreous', q: 'Drusen are deposits found between:', options: ['NFL and ganglion cells', 'RPE and Bruch membrane', 'Photoreceptors and RPE', 'Sclera and choroid', 'Vitreous and ILM'], correct: 1, explanation: 'Drusen are extracellular deposits located between the RPE basement membrane and the inner collagenous layer of Bruch membrane; hallmark of AMD.' },
  { id: 129, topic: 'Retina & Vitreous', q: 'Most common indication for pars plana vitrectomy:', options: ['Cataract', 'Vitreous haemorrhage / retinal detachment / epiretinal membrane', 'Glaucoma', 'Corneal ulcer', 'Pterygium'], correct: 1, explanation: 'PPV is most often performed for vitreous haemorrhage, complex/tractional retinal detachment, epiretinal membrane, macular hole, and complicated diabetic eye disease.' },
  { id: 130, topic: 'Retina & Vitreous', q: 'Branch retinal vein occlusion is most often located at:', options: ['Centre of disc', 'Site of arteriovenous crossing in superotemporal quadrant', 'Macula', 'Far peripheral retina', 'Optic chiasm'], correct: 1, explanation: 'BRVO usually occurs at arteriovenous crossings (commonly superotemporal) where a sclerosed artery compresses the underlying vein.' },

  // ============ Neuro-ophthalmology (20) ============
  { id: 131, topic: 'Neuro-ophthalmology', q: 'A relative afferent pupillary defect (RAPD) localises pathology to:', options: ['Iris sphincter', 'Cataract', 'Optic nerve or extensive retinal disease in one eye', 'Cornea', 'Ciliary body'], correct: 2, explanation: 'RAPD reflects asymmetric afferent input – usually optic nerve disease or large retinal pathology; never caused by media opacities like cataract.' },
  { id: 132, topic: 'Neuro-ophthalmology', q: 'A pituitary adenoma compressing the chiasm classically causes:', options: ['Bitemporal hemianopia', 'Homonymous hemianopia', 'Central scotoma', 'Altitudinal defect', 'Ring scotoma'], correct: 0, explanation: 'Chiasmal compression interrupts decussating nasal retinal fibres producing bitemporal hemianopia.' },
  { id: 133, topic: 'Neuro-ophthalmology', q: 'Light-near dissociation with small irregular pupils is termed:', options: ['Adie tonic pupil', 'Argyll Robertson pupil', 'Horner syndrome', 'CN III palsy', 'Marcus Gunn pupil'], correct: 1, explanation: 'Argyll Robertson pupils ("prostitute\'s pupils") are small, irregular pupils that accommodate but do not react to light; classically associated with neurosyphilis.' },
  { id: 134, topic: 'Neuro-ophthalmology', q: 'Horner syndrome triad:', options: ['Ptosis, miosis, anhidrosis', 'Ptosis, mydriasis, exotropia', 'Diplopia, pain, mydriasis', 'Proptosis, lid lag, lid retraction', 'Anisocoria with mydriasis on the affected side'], correct: 0, explanation: 'Horner syndrome = ptosis (mild), miosis, anhidrosis on the same side from sympathetic chain interruption.' },
  { id: 135, topic: 'Neuro-ophthalmology', q: 'Pupil-sparing third nerve palsy in an older diabetic adult most likely results from:', options: ['Posterior communicating artery aneurysm', 'Microvascular ischemic mononeuropathy', 'Brainstem stroke', 'Cavernous sinus thrombosis', 'Tolosa-Hunt syndrome'], correct: 1, explanation: 'Pupil-sparing CN III palsy in diabetics is typically ischemic; pupil-involving palsy requires urgent imaging to exclude aneurysm.' },
  { id: 136, topic: 'Neuro-ophthalmology', q: 'Optic neuritis classically presents with:', options: ['Painless gradual visual loss', 'Painful monocular subacute vision loss in young woman with RAPD', 'Bilateral simultaneous vision loss', 'Sudden total blindness without RAPD', 'Cherry-red spot'], correct: 1, explanation: 'Demyelinating optic neuritis (often MS) presents with pain on eye movement and subacute monocular vision loss with RAPD in young women.' },
  { id: 137, topic: 'Neuro-ophthalmology', q: 'Most common cause of acute non-arteritic anterior ischemic optic neuropathy (NAION):', options: ['Giant cell arteritis', 'Crowded "disc at risk" with small cup', 'Optic nerve glioma', 'Idiopathic intracranial hypertension', 'CMV'], correct: 1, explanation: 'NAION typically occurs in patients with small crowded optic discs ("disc at risk"); painless monocular altitudinal field loss; vasculopathic risk factors common.' },
  { id: 138, topic: 'Neuro-ophthalmology', q: 'In suspected giant cell arteritis the initial management is:', options: ['Await temporal artery biopsy', 'Start high-dose systemic corticosteroids immediately, then biopsy', 'Topical steroid', 'Aspirin alone', 'No treatment until ESR confirmed'], correct: 1, explanation: 'Suspected GCA is a sight- and life-threatening emergency: start high-dose corticosteroids (IV methylprednisolone or oral prednisolone) immediately and biopsy within 1-2 weeks.' },
  { id: 139, topic: 'Neuro-ophthalmology', q: 'Internuclear ophthalmoplegia is due to a lesion of:', options: ['CN VI nucleus', 'Medial longitudinal fasciculus', 'Frontal eye field', 'Cerebellum', 'Occipital cortex'], correct: 1, explanation: 'INO arises from MLF lesion; on attempted horizontal gaze the adducting eye is slow/weak and the abducting eye shows nystagmus. Common in MS (young, bilateral) and stroke (older, unilateral).' },
  { id: 140, topic: 'Neuro-ophthalmology', q: 'Idiopathic intracranial hypertension classically affects:', options: ['Elderly men', 'Young obese women of childbearing age', 'Children with leukocoria', 'Neonates with cataract', 'Postmenopausal women'], correct: 1, explanation: 'IIH (pseudotumor cerebri) typically affects obese women of reproductive age with headache, transient visual obscurations, papilloedema.' },
  { id: 141, topic: 'Neuro-ophthalmology', q: 'Best initial test in suspected IIH:', options: ['CT head only', 'MRI brain with venography then LP after imaging if normal', 'Lumbar puncture first without imaging', 'EEG', 'Visual field alone'], correct: 1, explanation: 'Neuroimaging (MRI ± MRV) rules out a mass/venous sinus thrombosis before performing LP; CSF opening pressure >25 cmH₂O is diagnostic.' },
  { id: 142, topic: 'Neuro-ophthalmology', q: 'Visual field defect with right temporal lobe lesion (Meyer\'s loop):', options: ['Right superior quadrantanopia', 'Left superior quadrantanopia ("pie in the sky")', 'Bitemporal hemianopia', 'Central scotoma', 'Altitudinal defect'], correct: 1, explanation: 'Lesions of Meyer\'s loop in temporal lobe cause contralateral homonymous superior quadrantanopia ("pie in the sky").' },
  { id: 143, topic: 'Neuro-ophthalmology', q: 'A dilated, slowly reacting pupil with sectoral palsy responsive to dilute pilocarpine 0.125% suggests:', options: ['CN III palsy', 'Adie tonic pupil', 'Horner syndrome', 'Pharmacologic mydriasis', 'Argyll Robertson pupil'], correct: 1, explanation: 'Adie\'s tonic pupil (post-ganglionic parasympathetic denervation) shows denervation hypersensitivity – constricts to dilute pilocarpine 0.125%.' },
  { id: 144, topic: 'Neuro-ophthalmology', q: 'Cocaine 4 % drops in Horner syndrome:', options: ['Cause greater dilation in affected eye', 'Fail to dilate the affected pupil', 'Constrict both pupils', 'Have no effect', 'Cause permanent miosis'], correct: 1, explanation: 'Cocaine blocks noradrenaline reuptake; in Horner the sympathetic chain releases less NA so the affected pupil dilates poorly compared with normal.' },
  { id: 145, topic: 'Neuro-ophthalmology', q: 'Most common cause of bilateral optic disc swelling with normal visual acuity:', options: ['Optic neuritis', 'Papilloedema due to raised ICP', 'Toxic optic neuropathy', 'AION', 'Optic nerve glioma'], correct: 1, explanation: 'True papilloedema (bilateral disc oedema secondary to raised intracranial pressure) typically preserves visual acuity early; field shows enlarged blind spot.' },
  { id: 146, topic: 'Neuro-ophthalmology', q: 'Leber hereditary optic neuropathy is:', options: ['Autosomal dominant', 'X-linked', 'Mitochondrial (matrilineal)', 'Autosomal recessive', 'Sporadic'], correct: 2, explanation: 'LHON is a mitochondrial DNA disorder (e.g. mt11778, mt14484, mt3460) presenting with sequential bilateral subacute optic neuropathy in young males.' },
  { id: 147, topic: 'Neuro-ophthalmology', q: 'Marcus Gunn jaw-winking is co-firing of:', options: ['Facial and trigeminal', 'Trigeminal (pterygoid) and oculomotor (levator)', 'Facial and oculomotor', 'Trigeminal and facial', 'Trigeminal and abducens'], correct: 1, explanation: 'Marcus Gunn jaw winking phenomenon: synkinesis between the trigeminal-innervated pterygoid and the levator (CN III), causing lid elevation on jaw movement.' },
  { id: 148, topic: 'Neuro-ophthalmology', q: 'Optic disc swelling, severe vision loss, and pain on eye movement in a young patient suggests:', options: ['Papilloedema', 'Anterior demyelinating optic neuritis', 'AION', 'NAION', 'CRAO'], correct: 1, explanation: 'Pain on eye movement, monocular vision loss with RAPD, and disc swelling in a young adult points to anterior demyelinating optic neuritis (often MS).' },
  { id: 149, topic: 'Neuro-ophthalmology', q: 'Bilateral lid retraction with lid lag on downgaze in a Graves patient is termed:', options: ['Dalrymple sign and Von Graefe sign', 'Argyll Robertson pupil', 'Charles Bell phenomenon', 'Stellwag sign only', 'Hertoghs sign'], correct: 0, explanation: 'Dalrymple sign = upper lid retraction at primary gaze. Von Graefe sign = lid lag on downgaze – both classic for thyroid eye disease.' },
  { id: 150, topic: 'Neuro-ophthalmology', q: 'Most useful investigation for atypical optic neuritis suspecting NMOSD:', options: ['MRI brain only', 'Serum aquaporin-4 IgG (AQP4) and MOG antibody testing', 'CSF protein only', 'VEP only', 'OCT alone'], correct: 1, explanation: 'In atypical optic neuritis (bilateral, severe, longitudinal cord lesions), test for AQP4-IgG (NMOSD) and MOG-IgG; treatment differs from MS.' },

  // ============ Strabismus & Pediatric (20) ============
  { id: 151, topic: 'Strabismus & Pediatric', q: 'A child with leukocoria, strabismus, and a heritable family history – most concerning diagnosis:', options: ['Congenital cataract', 'Retinoblastoma', 'Persistent fetal vasculature', 'Coats disease', 'Toxocariasis'], correct: 1, explanation: 'Leukocoria in a child must rule out retinoblastoma – the most common intra-ocular malignancy in childhood, often heritable (RB1 mutation).' },
  { id: 152, topic: 'Strabismus & Pediatric', q: 'Critical period for visual development is approximately:', options: ['0–4 months', 'Birth to 7–8 years (sensitive in first 2 y)', 'Up to 18 years', '0–1 month only', '1–14 years'], correct: 1, explanation: 'Visual development is most sensitive in the first 2 years but plasticity extends to 7–8 years; amblyopia treatment is most effective during this period.' },
  { id: 153, topic: 'Strabismus & Pediatric', q: 'Most common type of childhood strabismus:', options: ['Infantile esotropia', 'Accommodative esotropia', 'Intermittent exotropia', 'Sensory esotropia', 'Brown syndrome'], correct: 1, explanation: 'Accommodative (refractive) esotropia is the most common childhood esotropia, typically presenting at 2-3 years in a hyperope; treated with full hypermetropic correction.' },
  { id: 154, topic: 'Strabismus & Pediatric', q: 'A child with constant esotropia from age 2 months, +0.50 D refraction, cross-fixation. Diagnosis:', options: ['Accommodative esotropia', 'Infantile (congenital) esotropia', 'Sensory esotropia', 'Sixth nerve palsy', 'Duane syndrome'], correct: 1, explanation: 'Infantile esotropia: onset before 6 months, large angle (>30 PD), minimal refractive error, with cross-fixation and latent nystagmus. Surgical correction by 18-24 months recommended.' },
  { id: 155, topic: 'Strabismus & Pediatric', q: 'Duane retraction syndrome type 1 features:', options: ['Limited abduction with globe retraction on adduction', 'Limited adduction with globe retraction on abduction', 'Limited up- and down-gaze', 'Bilateral elevation deficit', 'Normal ocular motility'], correct: 0, explanation: 'Duane type 1: limited abduction, globe retraction with narrowing of palpebral fissure on adduction due to absence of CN VI nucleus with aberrant CN III innervation of lateral rectus.' },
  { id: 156, topic: 'Strabismus & Pediatric', q: 'Brown syndrome involves:', options: ['Inferior oblique paresis', 'Superior oblique tendon-sheath restriction limiting elevation in adduction', 'Pulley anomaly of lateral rectus', 'Medial rectus restriction', 'Levator dehiscence'], correct: 1, explanation: 'Brown syndrome is restricted elevation in adduction (positive forced duction); congenital tight superior oblique tendon or acquired causes (trauma, inflammation).' },
  { id: 157, topic: 'Strabismus & Pediatric', q: 'Most important determinant of amblyopia treatment success:', options: ['Severity at presentation', 'Age at start of treatment and compliance', 'Type of strabismus', 'Refractive error magnitude', 'Use of atropine'], correct: 1, explanation: 'Earlier age and adherence to occlusion/atropine are the strongest predictors of amblyopia treatment success.' },
  { id: 158, topic: 'Strabismus & Pediatric', q: 'Krimsky test estimates:', options: ['Visual acuity', 'Stereopsis', 'Magnitude of strabismus by light reflex displacement and prisms', 'Pupil function', 'Colour vision'], correct: 2, explanation: 'Krimsky test: prisms placed in front of fixing eye until the corneal light reflex centres on the deviating eye, estimating the angle of strabismus.' },
  { id: 159, topic: 'Strabismus & Pediatric', q: 'Most common cause of childhood blindness in low-income countries:', options: ['Retinoblastoma', 'Vitamin A deficiency / measles', 'Cataract', 'ROP', 'Trauma'], correct: 1, explanation: 'Vitamin A deficiency (xerophthalmia) with measles infection remains a leading cause of preventable childhood blindness in low-income countries.' },
  { id: 160, topic: 'Strabismus & Pediatric', q: 'Cover-uncover test specifically detects:', options: ['Heterophoria', 'Manifest strabismus (heterotropia)', 'Refractive error', 'Visual acuity', 'Pupil defect'], correct: 1, explanation: 'Cover-uncover differentiates tropia (manifest) from phoria; the alternate cover test reveals total deviation including phorias.' },
  { id: 161, topic: 'Strabismus & Pediatric', q: 'Refractive error most associated with accommodative esotropia:', options: ['High myopia', 'Mild myopia', 'Moderate to high hyperopia (+3 to +6 D)', 'Mixed astigmatism', 'No refractive error'], correct: 2, explanation: 'Uncorrected hyperopia (often +3-6 D) triggers excessive accommodation and accommodative convergence, producing esotropia.' },
  { id: 162, topic: 'Strabismus & Pediatric', q: 'Bagolini striated glass test assesses:', options: ['Refraction', 'Sensory binocular status under near-normal viewing', 'IOP', 'Pupil reactions', 'Colour vision'], correct: 1, explanation: 'Bagolini lenses produce streaks through both eyes, identifying suppression, ARC, or normal correspondence under conditions closest to natural viewing.' },
  { id: 163, topic: 'Strabismus & Pediatric', q: 'In a child with retinoblastoma, the most concerning prognostic feature is:', options: ['Unilateral disease', 'Optic nerve invasion beyond lamina cribrosa or extraocular extension', 'Subretinal seeding only', 'Anterior segment seeding only', 'Calcification on USG'], correct: 1, explanation: 'Extraocular extension, optic nerve invasion past the lamina cribrosa, and choroidal invasion are high-risk features requiring systemic chemotherapy and orbital radiation.' },
  { id: 164, topic: 'Strabismus & Pediatric', q: 'Stereopsis is typically tested with:', options: ['Snellen chart', 'Titmus fly / TNO / Lang test', 'Ishihara plates', 'Goldmann perimetry', 'Pelli-Robson chart'], correct: 1, explanation: 'Stereoacuity is measured with Titmus (fly, animals, circles), TNO (random-dot), Lang and Frisby tests – essential to confirm binocular function.' },
  { id: 165, topic: 'Strabismus & Pediatric', q: 'Hering\'s law of equal innervation predicts:', options: ['Each eye moves independently', 'Yoke muscles receive equal innervation', 'Antagonist muscles relax during contraction of agonist', 'Vergence is independent of version', 'Saccades are slower than smooth pursuit'], correct: 1, explanation: 'Hering\'s law: paired yoke muscles in the two eyes receive equal and simultaneous innervation, producing conjugate eye movements.' },
  { id: 166, topic: 'Strabismus & Pediatric', q: 'A 3-year-old presents with progressive proptosis and "raccoon eyes". Suspect:', options: ['Capillary haemangioma', 'Neuroblastoma metastasis to orbit', 'Retinoblastoma', 'Optic glioma', 'Rhabdomyosarcoma'], correct: 1, explanation: 'Metastatic neuroblastoma classically causes rapidly progressive proptosis with periorbital ecchymosis ("raccoon eyes") in young children.' },
  { id: 167, topic: 'Strabismus & Pediatric', q: 'Most common orbital malignancy of childhood:', options: ['Retinoblastoma', 'Rhabdomyosarcoma', 'Lymphoma', 'Neurofibroma', 'Dermoid'], correct: 1, explanation: 'Rhabdomyosarcoma is the most common primary orbital malignancy in children (peak 5–7 y); presents with rapid unilateral proptosis – urgent biopsy.' },
  { id: 168, topic: 'Strabismus & Pediatric', q: 'Refractive correction in infant with congenital cataract is most commonly via:', options: ['Spectacles only', 'IOL implantation at primary surgery in all', 'Contact lenses (often aphakic correction)', 'Refractive surgery', 'Pinhole spectacles'], correct: 2, explanation: 'For infants <6-12 months, aphakic spectacles or contact lenses (extended-wear silicone hydrogel) are preferred; IOL implantation is increasingly used after 6-12 months.' },
  { id: 169, topic: 'Strabismus & Pediatric', q: 'A vertical deviation that increases when fixating eye is adducted suggests:', options: ['Inferior oblique overaction', 'Superior oblique palsy', 'Brown syndrome', 'Duane syndrome', 'Sixth nerve palsy'], correct: 1, explanation: 'Park\'s three-step test: in superior oblique palsy a hypertropia worsens in contralateral gaze and ipsilateral head tilt (Bielschowsky positive).' },
  { id: 170, topic: 'Strabismus & Pediatric', q: 'Worth four-dot test seeing two red and one green light suggests:', options: ['Normal binocular vision', 'Suppression of one eye', 'Diplopia', 'ARC', 'Amblyopia'], correct: 1, explanation: 'Worth four-dot: seeing only the red lights (2 reds) indicates left eye suppression (red filter is usually over right eye).' },

  // ============ Oculoplastics & Orbit (15) ============
  { id: 171, topic: 'Oculoplastics & Orbit', q: 'Most common cause of unilateral proptosis in adults:', options: ['Orbital tumour', 'Thyroid eye disease', 'Orbital cellulitis', 'Trauma', 'Mucocele'], correct: 1, explanation: 'Thyroid eye disease (Graves\') is the most common cause of unilateral and bilateral proptosis in adults.' },
  { id: 172, topic: 'Oculoplastics & Orbit', q: 'In thyroid eye disease the most commonly enlarged extraocular muscle is:', options: ['Lateral rectus', 'Inferior rectus and medial rectus (sparing tendons)', 'Superior oblique', 'Levator', 'Inferior oblique'], correct: 1, explanation: 'TED most often enlarges inferior and medial recti (mnemonic "I\'M SLOw"). The tendinous insertions are characteristically spared.' },
  { id: 173, topic: 'Oculoplastics & Orbit', q: 'Most common cause of acquired blepharoptosis in adults:', options: ['Levator dehiscence (aponeurotic)', 'Third nerve palsy', 'Horner syndrome', 'Myasthenia gravis', 'Congenital myogenic ptosis'], correct: 0, explanation: 'Involutional aponeurotic ptosis (disinsertion or thinning of the levator aponeurosis) is the most common cause of acquired adult ptosis.' },
  { id: 174, topic: 'Oculoplastics & Orbit', q: 'Definition of orbital cellulitis vs preseptal:', options: ['Both involve postseptal structures', 'Orbital cellulitis involves structures POSTERIOR to orbital septum (proptosis, ophthalmoplegia, pain)', 'Preseptal involves muscles', 'Distinguished by fever alone', 'No clinical difference'], correct: 1, explanation: 'Orbital cellulitis is postseptal infection with proptosis, painful ophthalmoplegia, ↓ vision, often from ethmoid sinusitis. Preseptal infection is anterior to the orbital septum and does not have these features.' },
  { id: 175, topic: 'Oculoplastics & Orbit', q: 'A bony "tear-drop" sign on coronal CT suggests:', options: ['Orbital cellulitis', 'Blow-out fracture of the orbital floor with herniated tissue', 'Mucocele', 'Optic nerve glioma', 'Pseudotumor'], correct: 1, explanation: 'Orbital floor blowout fractures show herniation of orbital contents into the maxillary sinus producing a tear-drop sign; muscle entrapment with diplopia indicates need for surgical repair.' },
  { id: 176, topic: 'Oculoplastics & Orbit', q: 'Most common malignant eyelid tumour:', options: ['Basal cell carcinoma', 'Squamous cell carcinoma', 'Sebaceous gland carcinoma', 'Melanoma', 'Merkel cell carcinoma'], correct: 0, explanation: 'BCC accounts for ~90% of malignant eyelid tumours; commonly affects the lower lid medial canthal area.' },
  { id: 177, topic: 'Oculoplastics & Orbit', q: 'Sebaceous gland carcinoma is most often mistaken for:', options: ['Chalazion or chronic blepharitis', 'Stye only', 'Allergic conjunctivitis', 'Pterygium', 'Pinguecula'], correct: 0, explanation: 'Sebaceous carcinoma may masquerade as recurrent chalazion or chronic unilateral blepharoconjunctivitis – biopsy any suspicious recurrent lid lesion.' },
  { id: 178, topic: 'Oculoplastics & Orbit', q: 'Levator function ≥10 mm with margin reflex distance 1 reduction is classified as:', options: ['Severe ptosis with poor function', 'Mild-moderate ptosis with good function – aponeurotic repair appropriate', 'Congenital myogenic ptosis requiring frontalis sling', 'Normal lid', 'Myasthenic ptosis'], correct: 1, explanation: 'Good levator function (>10 mm) with mild–moderate ptosis is typically treated with anterior aponeurotic repair or Müller muscle resection rather than a frontalis sling.' },
  { id: 179, topic: 'Oculoplastics & Orbit', q: 'Treatment of choice for symptomatic acquired nasolacrimal duct obstruction in adults:', options: ['Dacryocystorhinostomy (DCR)', 'Probing alone', 'Antibiotic drops', 'Repeated syringing', 'Punctal cautery'], correct: 0, explanation: 'External or endoscopic DCR creating an anastomosis between the lacrimal sac and nasal cavity is the definitive treatment for adult NLD obstruction.' },
  { id: 180, topic: 'Oculoplastics & Orbit', q: 'Cavernous hemangioma of the orbit typically:', options: ['Is a malignant childhood tumour', 'Is a well-encapsulated benign vascular mass in adult women causing gradual proptosis', 'Causes acute severe pain', 'Always invades muscles', 'Regresses spontaneously'], correct: 1, explanation: 'Cavernous hemangioma is the commonest benign orbital tumour in adults, a slowly growing encapsulated intraconal mass best removed surgically.' },
  { id: 181, topic: 'Oculoplastics & Orbit', q: 'Dermoid cyst of orbit most commonly occurs at:', options: ['Inferomedial orbit', 'Superotemporal orbit at frontozygomatic suture', 'Apex of orbit', 'Lacrimal sac', 'Lacrimal gland'], correct: 1, explanation: 'Dermoid cysts arise at suture lines, most commonly the superotemporal orbit at the frontozygomatic suture in children.' },
  { id: 182, topic: 'Oculoplastics & Orbit', q: 'Most common cause of acute dacryocystitis:', options: ['Viral conjunctivitis', 'Nasolacrimal duct obstruction with secondary bacterial infection (Staph/Strep)', 'Sarcoidosis', 'Wegener granulomatosis', 'Fungal infection'], correct: 1, explanation: 'Acute dacryocystitis usually arises from chronic NLD obstruction with secondary bacterial infection (Staph aureus, Streptococci); urgent antibiotics ± I&D.' },
  { id: 183, topic: 'Oculoplastics & Orbit', q: 'In thyroid eye disease, the most sight-threatening complication is:', options: ['Exposure keratopathy', 'Compressive optic neuropathy at the orbital apex', 'Lid retraction', 'Dry eye', 'Strabismus'], correct: 1, explanation: 'Compressive optic neuropathy from crowded muscles at the orbital apex is the major sight-threatening complication and requires urgent steroids/orbital decompression.' },
  { id: 184, topic: 'Oculoplastics & Orbit', q: 'Entropion of the lower lid in elderly is most commonly:', options: ['Cicatricial', 'Congenital', 'Involutional (laxity)', 'Mechanical', 'Spastic only'], correct: 2, explanation: 'Involutional entropion (horizontal lid laxity, lower lid retractor disinsertion, overriding pre-septal orbicularis) is the commonest type in elderly patients.' },
  { id: 185, topic: 'Oculoplastics & Orbit', q: 'Hertel exophthalmometry measures:', options: ['Globe diameter', 'Anterior projection of the cornea from the lateral orbital rim', 'Axial length', 'IOP', 'Lid height'], correct: 1, explanation: 'Hertel exophthalmometer measures the anterior projection of the cornea (in mm) from the lateral orbital rim; normal <21 mm, asymmetry >2 mm is significant.' },

  // ============ Ocular Pathology (10) ============
  { id: 186, topic: 'Ocular Pathology', q: 'The most common primary intraocular malignancy in adults is:', options: ['Choroidal melanoma', 'Retinoblastoma', 'Choroidal hemangioma', 'Iris naevus', 'Conjunctival lymphoma'], correct: 0, explanation: 'Uveal (choroidal) melanoma is the most common primary intraocular malignancy in adults (~85% of uveal melanomas are choroidal).' },
  { id: 187, topic: 'Ocular Pathology', q: 'The Callender classification of uveal melanoma divides cells into:', options: ['Polygonal vs sarcomatous', 'Spindle A, spindle B, epithelioid, mixed, necrotic', 'Small, medium, large', 'Glandular, papillary, lymphoid', 'Benign vs malignant only'], correct: 1, explanation: 'Callender: spindle A (best prognosis), spindle B, mixed (commonest), epithelioid (worst), necrotic. Epithelioid cells indicate worse prognosis.' },
  { id: 188, topic: 'Ocular Pathology', q: 'Flexner-Wintersteiner rosettes are characteristic of:', options: ['Choroidal melanoma', 'Retinoblastoma', 'Optic nerve glioma', 'Medulloepithelioma', 'Lymphoma'], correct: 1, explanation: 'Flexner-Wintersteiner rosettes (cells around a central lumen) are a hallmark of well-differentiated retinoblastoma; Homer Wright rosettes are also seen.' },
  { id: 189, topic: 'Ocular Pathology', q: 'Cytogenetic abnormality strongly associated with metastasis in uveal melanoma:', options: ['Trisomy 21', 'Monosomy 3', 'BRCA1 mutation', 'BCR-ABL', 'Trisomy 8 alone'], correct: 1, explanation: 'Monosomy 3 (often with chromosome 8q gain) on biopsy of choroidal melanoma confers significantly increased risk of metastasis.' },
  { id: 190, topic: 'Ocular Pathology', q: 'Pterygium histology shows:', options: ['Granuloma formation', 'Elastotic degeneration of subepithelial collagen with vascular invasion', 'Necrotic vasculitis', 'Lymphoid hyperplasia', 'Sebaceous proliferation'], correct: 1, explanation: 'Pterygium shows actinic elastotic degeneration of subepithelial collagen with fibrovascular tissue invading the cornea.' },
  { id: 191, topic: 'Ocular Pathology', q: 'Asteroid hyalosis is composed of:', options: ['Calcium soaps within the vitreous', 'Cholesterol crystals (synchysis scintillans)', 'Pigment granules', 'Blood cells', 'Asteroid cells'], correct: 0, explanation: 'Asteroid bodies are calcium-containing lipid (calcium phosphate soap) spheres suspended in vitreous; usually unilateral, asymptomatic, age-related.' },
  { id: 192, topic: 'Ocular Pathology', q: 'Drusen on histology show:', options: ['Hyperplasia of RPE alone', 'Eosinophilic deposits between RPE basement membrane and inner collagenous layer of Bruch', 'Sub-retinal fluid', 'Calcific plaques', 'Lipid in choriocapillaris'], correct: 1, explanation: 'Drusen are PAS-positive eosinophilic extracellular deposits between RPE basement membrane and Bruch\'s inner collagenous layer.' },
  { id: 193, topic: 'Ocular Pathology', q: 'Granulomatous inflammation in the eye is typified by:', options: ['Neutrophils predominant', 'Epithelioid cells, lymphocytes, ± multinucleate giant cells', 'Plasma cells only', 'Eosinophils predominant', 'Mast cells'], correct: 1, explanation: 'Granulomatous inflammation has epithelioid macrophages, lymphocytes and multinucleated giant cells – seen in TB, sarcoid, sympathetic ophthalmia, phacoanaphylaxis.' },
  { id: 194, topic: 'Ocular Pathology', q: 'A pigmented conjunctival lesion increasing in size with surrounding melanosis in an elderly white patient most concerning for:', options: ['Pinguecula', 'Conjunctival melanoma arising from primary acquired melanosis with atypia', 'Naevus', 'Pterygium', 'Hemangioma'], correct: 1, explanation: 'Conjunctival melanoma often arises from PAM with atypia; suspicious features include enlargement, nodularity, vascularity, increased pigmentation.' },
  { id: 195, topic: 'Ocular Pathology', q: 'Demarcation line on histology of corneal scarring originates from:', options: ['Epithelium', 'Bowman layer regenerating', 'Stromal fibroblast activation', 'Endothelial migration', 'Mucin gland'], correct: 2, explanation: 'Bowman layer does not regenerate. Corneal scars consist of disorganised collagen produced by activated keratocytes/myofibroblasts in the stroma.' },

  // ============ Pharmacology (5) ============
  { id: 196, topic: 'Pharmacology', q: 'Topical timolol can cause systemic adverse effects via:', options: ['Skin absorption', 'Beta-1 receptor blockade after nasolacrimal absorption causing bradycardia, bronchospasm', 'Direct optic nerve effect', 'Hypoglycaemia only', 'Renal failure'], correct: 1, explanation: 'Drops absorbed via nasolacrimal mucosa bypass first-pass metabolism; non-selective β blockade can cause bradycardia, hypotension, bronchospasm – contraindicated in asthma and heart block.' },
  { id: 197, topic: 'Pharmacology', q: 'Most common ocular side effect of topical prostaglandin analogues:', options: ['Cataract', 'Conjunctival hyperaemia, lash hypertrichosis, iris pigmentation, periocular pigmentation', 'Corneal ulceration', 'Glaucoma worsening', 'Retinal detachment'], correct: 1, explanation: 'PGAs cause hyperaemia, iris darkening (especially mixed-colour irises), eyelash growth/thickening, and periocular skin pigmentation.' },
  { id: 198, topic: 'Pharmacology', q: 'Chloroquine/hydroxychloroquine retinopathy is best screened with:', options: ['Snellen acuity alone', 'SD-OCT, automated 10-2 visual field, FAF and mfERG', 'Ishihara test alone', 'Goldmann perimetry only', 'B-scan ultrasound'], correct: 1, explanation: 'AAO 2016 screening uses SD-OCT, 10-2 visual field, and ideally FAF and mfERG; classic finding is parafoveal photoreceptor loss ("flying saucer sign" on OCT).' },
  { id: 199, topic: 'Pharmacology', q: 'Vigabatrin can cause:', options: ['Cataract', 'Bilateral concentric visual-field constriction', 'Optic neuritis', 'Macular oedema', 'Pigmentary retinopathy'], correct: 1, explanation: 'Vigabatrin (anti-epileptic) causes irreversible bilateral concentric peripheral visual field loss; periodic visual field testing is mandatory.' },
  { id: 200, topic: 'Pharmacology', q: 'Most common cause of bilateral toxic optic neuropathy worldwide:', options: ['Methanol poisoning', 'Ethambutol', 'Chloramphenicol', 'Cyclosporine', 'Vincristine'], correct: 1, explanation: 'Ethambutol-induced optic neuropathy is dose-related (typically >15 mg/kg/day for prolonged periods), reversible if drug stopped early; characteristic central or centrocaecal scotoma with red-green dyschromatopsia.' },
];
